#!/usr/bin/env node
/**
 * Generates src/lib/schema.pg.sql from src/lib/schema.sql.
 *
 * The SQLite schema was written to be portable, so the transformation is small
 * and mechanical — no table is redesigned and no constraint is dropped:
 *
 *   INTEGER PRIMARY KEY AUTOINCREMENT  →  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY
 *   TEXT DEFAULT (datetime('now'))     →  TEXT DEFAULT to_char(now() AT TIME ZONE 'utc', …)
 *   PRAGMA …                           →  removed (Postgres has no equivalent)
 *   REFERENCES … ON DELETE CASCADE     →  unchanged (identical semantics)
 *
 * Only `id` becomes an identity column. Every other column stays TEXT/REAL/
 * INTEGER as in SQLite, because the application stores ISO date strings and
 * compares them lexicographically — keeping the same types is what makes one
 * query set work on both engines.
 *
 *   node scripts/gen-pg-schema.mjs
 */
import fs from "node:fs";

const SRC = "src/lib/schema.sql";
const OUT = "src/lib/schema.pg.sql";

const NOW_TEXT = `(to_char(now() AT TIME ZONE 'utc', 'YYYY-MM-DD HH24:MI:SS'))`;

let sql = fs.readFileSync(SRC, "utf8");

// 1. SQLite-only pragmas
sql = sql.split("\n").filter((l) => !/^\s*PRAGMA\s/i.test(l)).join("\n");

// 2. AUTOINCREMENT primary keys → identity columns
sql = sql.replace(
  /(\w+)\s+INTEGER\s+PRIMARY\s+KEY\s+AUTOINCREMENT/gi,
  "$1 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY"
);

// 3. datetime('now') defaults
sql = sql.replace(/DEFAULT\s*\(datetime\('now'\)\)/gi, `DEFAULT ${NOW_TEXT}`);
sql = sql.replace(/DEFAULT\s+datetime\('now'\)/gi, `DEFAULT ${NOW_TEXT}`);

// 4. any remaining explicit INTEGER PRIMARY KEY (non-auto) stays as-is — valid in PG.

// 5. `TEXT NOT NULL UNIQUE COLLATE NOCASE` is SQLite-only syntax. In Postgres a
//    plain UNIQUE is CASE-SENSITIVE, which would let "Admin@x" and "admin@x"
//    both register. Replace it with a real case-insensitive unique index so the
//    behaviour matches the SQLite build exactly.
sql = sql.replace(/\s*COLLATE\s+NOCASE/gi, "");
const extraIndexes = [];
if (/(CREATE TABLE IF NOT EXISTS users \([\s\S]*?email TEXT NOT NULL UNIQUE)/.test(sql)) {
  extraIndexes.push(
    "CREATE UNIQUE INDEX IF NOT EXISTS idx_users_email_ci ON users (lower(email));"
  );
}

// 6. Header
// drop the SQLite file's own banner
sql = sql.replace(/^--[^\n]*\n(--[^\n]*\n)*\n*/, "");

const header = `-- RentLink 3D — relational schema (PostgreSQL)
--
-- GENERATED FILE — do not edit by hand. Source of truth is src/lib/schema.sql;
-- regenerate with: node scripts/gen-pg-schema.mjs
--
-- Only difference from the SQLite schema: "id" columns are identity columns and
-- timestamps default to a UTC "YYYY-MM-DD HH:MM:SS" text value. All other column
-- types and every relationship/constraint are preserved exactly.

`;

if (extraIndexes.length) {
  sql = `${sql.trim()}\n\n-- case-insensitive uniqueness (matches SQLite COLLATE NOCASE)\n${extraIndexes.join("\n")}\n`;
}
fs.writeFileSync(OUT, header + sql.trim() + "\n");
console.log(`wrote ${OUT} (${sql.split("\n").length} lines)`);

// Sanity checks — fail loudly if the source grows something we cannot translate.
const leftovers = [
  [/AUTOINCREMENT/i, "AUTOINCREMENT"],
  [/PRAGMA/i, "PRAGMA"],
  [/datetime\('now'\)/i, "datetime('now')"],
];
for (const [re, label] of leftovers) {
  if (re.test(sql)) {
    console.error(`✗ untranslated ${label} remains in the generated schema`);
    process.exit(1);
  }
}
const tables = (sql.match(/CREATE TABLE/gi) ?? []).length;
const refs = (sql.match(/REFERENCES/gi) ?? []).length;
const indexes = (sql.match(/CREATE (UNIQUE )?INDEX/gi) ?? []).length;
console.log(`  ${tables} tables, ${refs} foreign keys, ${indexes} indexes`);
